var caseLibrary={'hubble-v1':{id:'hubble-v1',shortTitle:'Hubble investigation',questions:cases,sources:[{title:'NASA: Hubble’s Mirror Flaw',url:'https://science.nasa.gov/mission/hubble/observatory/design/optics/hubbles-mirror-flaw/'}]},'apollo13-air-v1':{"id": "apollo13-air-v1", "version": 1, "title": "Apollo 13: make the spare supplies usable", "shortTitle": "Apollo 13 investigation", "estimatedMinutes": 8, "introduction": "An Apollo 13 equipment failure changed the goal from landing on the Moon to returning the crew safely. Three astronauts sheltered in the lunar module. Investigate one part of the recovery: keeping carbon dioxide from building up in their air. All the technical information needed is in the clues.", "glossary": "A carbon dioxide cartridge contains material that removes carbon dioxide from air passing through it. Removing this gas is a different task from supplying oxygen.", "sources": [{"id": "mission", "title": "NASA: Apollo 13 Mission Details", "url": "https://www.nasa.gov/missions/apollo/apollo-13-mission-details/", "supports": "The change of mission, use of the lunar module, sufficient cartridge material but incompatible fittings, and the crew's safe return."}, {"id": "history", "title": "NASA: Houston, We've Had a Problem", "url": "https://www.nasa.gov/history/houston-weve-had-a-problem/", "supports": "An adaptor using replicas of onboard supplies, an altitude-chamber test, instructions sent to the crew, and a significant fall in carbon dioxide after installation."}, {"id": "artifact", "title": "NASA: Apollo 13 Lunar Module Mail Box", "url": "https://www.nasa.gov/image-article/apollo-13-lunar-module-mail-box/", "supports": "The improvised cartridge arrangement and its ground design and testing."}], "sourceNotice": "Opening the NASA sources reveals later clues and the historical solution. Historical details are paraphrased. The questions, options and reasoning feedback are written for this activity.", "questions": [{"id": "a13c1", "title": "Find the missing condition", "skill": "Evidence reasoning", "reasoningTarget": "Distinguish available resources from usable resources.", "clue": "The lunar module's carbon dioxide removal capacity was stretched by the longer stay and extra crew member. Spare cartridges were available in the command module. Across the two modules there was enough absorbing material.", "question": "Which check most directly establishes whether those spares can help?", "options": ["Check which module originally carried the larger cartridge supply.", "Check whether cabin air can be routed through the spare cartridges.", "Check how much electrical power remains for the journey home."], "answer": 1, "hint": "Having enough of a resource does not establish that the working system can use it.", "feedback": "The spare material is useful only if air can pass through it. The actual obstacle was a mismatch between the cartridge fittings. Supply history does not settle that issue. Electrical power matters to the wider rescue but does not by itself establish that the spares can work.", "other": "All three questions concern the mission. Focus on the missing condition between having a spare cartridge and using it to clean the cabin air.", "sourceIds": ["mission"]}, {"id": "a13c2", "title": "Choose a relevant test", "skill": "Evidence reasoning", "reasoningTarget": "Match a proposed test to real operating constraints.", "clue": "The command module cartridges did not fit the lunar module system directly. Engineers proposed a connector. The crew could build it only from materials already onboard; new parts could not be delivered.", "question": "Which test offers the strongest evidence that this proposal is usable?", "options": ["Test air cleaning with a laboratory connector, then adapt its parts for the crew.", "Rehearse the crew's assembly steps, then check air cleaning after installation.", "Test air cleaning with onboard-equivalent parts under representative conditions."], "answer": 2, "hint": "Consider both whether the design works and whether the crew can reproduce it with the available materials.", "feedback": "A relevant test keeps the material limits and operating conditions in view. A laboratory connector can test an idea but may depend on unavailable parts; an assembly rehearsal alone does not test air cleaning. NASA used replicas of onboard items and tested the arrangement in an altitude chamber before sending instructions.", "other": "Separate a test of one component or one step from evidence that the actual proposed arrangement will work within the crew's constraints.", "sourceIds": ["history", "artifact"]}, {"id": "a13c3", "title": "Keep the conclusion proportionate", "skill": "Evidence reasoning", "reasoningTarget": "State what an outcome supports without extending it to untested claims.", "clue": "After the ground test, the astronauts assembled the connector. NASA reports that carbon dioxide levels fell significantly within minutes of installing the first arrangement.", "question": "What does this new observation most strongly support?", "options": ["The installed arrangement improved air cleaning; its continued performance still needed monitoring.", "The original lunar-module cartridges had a manufacturing fault, rather than a capacity problem.", "The successful ground test would have been sufficient without checking the cabin's air."], "answer": 0, "hint": "Ask what the observed change tells you about the installed arrangement, and what it cannot establish about other causes or future performance.", "feedback": "The fall in carbon dioxide is direct evidence about the desired result onboard. It does not identify a manufacturing fault or remove the value of measuring the actual cabin air. Continued monitoring is our proposed reasoning step, not a quoted historical action from this clue.", "other": "Use the cabin measurement to support a limited conclusion. Avoid introducing an unobserved fault or treating a ground test as a substitute for checking the real result.", "sourceIds": ["history"]}], "answerKey": {"a13c1": 1, "a13c2": 2, "a13c3": 0}, "reflectionPrompt": "In two sentences, explain one decision using a clue. Then name something that decision or clue does not establish.", "historicalOutcome": "The makeshift connection enabled the crew to use spare cartridges for carbon dioxide removal. This was one part of a larger rescue involving power, water, navigation and re-entry. All three astronauts returned safely to Earth.", "evaluation": {"mode": "Fixed choices with optional ungraded explanation", "scoring": "Evaluate the first choice against the supplied key. Record hints, source opening, later attempts and prior familiarity separately. Explanations are retained without an automated quality score.", "novelty": "Use case ID plus question ID as the item key. A replay needs a new trial ID but remains familiar-item practice. Record prior familiarity if the learner already knows the story; a newly added case is not necessarily unfamiliar to that learner.", "limitation": "Three selected responses provide evidence about these questions, not a general reasoning, IQ or attention assessment.", "designNote": "This is a short introductory case. Correct choices require applying the supplied facts, not knowing the historical connector design. Later clues and the outcome should appear only after the preceding response."}, "authoringNotes": {"verifiedDate": "2026-09-18", "provenance": "Official NASA primary sources were opened and checked. No precise invented readings, timings beyond the reported minutes, or unobserved diagnostic outcomes are included.", "integration": "Register a13c1/a13c2/a13c3 in the server's immutable answer-key registry; never grade from a client-supplied answer property. Store caseTrial.caseId as apollo13-air-v1. If sources are opened before a response, record that exposure separately from an independent first attempt."}}};
